(6106530, 900197, 59029, '<td valign="top">attagirl!  You show that corn who''s boss! :0</td>', 'attagirl!  You show that corn who''s boss! :0', '2010-07-28 01:22:40.000000', NULL, 1),
(6106537, 899789, 59029, '<td valign="top">yum! 7</td>', 'yum! 7', '2010-07-28 01:24:44.000000', NULL, 1),
(6106541, 900055, 37845, '<td valign="top">That looks tasty. As for the photograph, I like the shallow DOF, and the balance of the table in the two corners. Well done.</td>', 'That looks tasty. As for the photograph, I like the shallow DOF, and the balance of the table in the two corners. Well done.', '2010-07-28 01:26:18.000000', NULL, 1),
(6106546, 900037, 59029, '<td valign="top">amazing textures and colours.  Would love to try some of that sometime! 8</td>', 'amazing textures and colours.  Would love to try some of that sometime! 8', '2010-07-28 01:27:23.000000', NULL, 1),
(6106548, 900033, 37845, '<td valign="top">A very appetizing shot. My only critique would be the fork in the bottom corner, and the beef in the background. I think if you got rid of both it would improve the photo. 7</td>', 'A very appetizing shot. My only critique would be the fork in the bottom corner, and the beef in the background. I think if you got rid of both it would improve the photo. 7', '2010-07-28 01:27:46.000000', NULL, 1),
(6106554, 898927, 59029, '<td valign="top">holy hamburger, Batman!  Either you used really teeny buns etc or one heckuva ton of meat.  Looks great! 8</td>', 'holy hamburger, Batman!  Either you used really teeny buns etc or one heckuva ton of meat.  Looks great! 8', '2010-07-28 01:28:46.000000', NULL, 1),
