(6110298, 899736, 118008, '<td valign="top">funny, but i wish the colors were more vibrant</td>', 'funny, but i wish the colors were more vibrant', '2010-07-31 10:19:09.000000', NULL, 1),
(6110299, 899152, 47470, '<td valign="top">Very well done.  I love that you were able to include the location, which gives much more of a sense of summer than any food could!  Great balance between the direct sun and shade.  The only thing I might change would be to white balance for the shade, since food looks tastier when the color cast is warmer rather than cool.  Not docking points for that though.</td>', 'Very well done.  I love that you were able to include the location, which gives much more of a sense of summer than any food could!  Great balance between the direct sun and shade.  The only thing I might change would be to white balance for the shade, since food looks tastier when the color cast is warmer rather than cool.  Not docking points for that though.', '2010-07-31 10:19:21.000000', NULL, 1),
(6110301, 900091, 118008, '<td valign="top">love the idea of the his and hers meals! just wish you had a solid background...maybe white or blue</td>', 'love the idea of the his and hers meals! just wish you had a solid background...maybe white or blue', '2010-07-31 10:20:33.000000', NULL, 1),
(6110302, 899807, 118008, '<td valign="top">needs to be focused more and i wish the colors were more vibrant</td>', 'needs to be focused more and i wish the colors were more vibrant', '2010-07-31 10:21:01.000000', NULL, 1),
(6110304, 899778, 118008, '<td valign="top">nice idea, i wish either the fork and knife or the last piece of food in the back was in focus...it would have made the picture 10 times better</td>', 'nice idea, i wish either the fork and knife or the last piece of food in the back was in focus...it would have made the picture 10 times better', '2010-07-31 10:22:05.000000', NULL, 1),
