(6116496, 899677, 22301, '<td valign="top">that bird is ambitious.</td>', 'that bird is ambitious.', '2010-08-04 01:10:01.000000', NULL, 0),
(6116499, 900194, 108891, '<td valign="top">Thanks for all the positive comments! This one was great fun, and at 5.9+ I believe I''ve made it to one of the infamous groups here on DPC!<br/> <br/>This juvenile yellow crowned night heron(?) snagged this meal from a lake near my apartment, dropped it on the levee he''s standing on, and fought for 20 minutes to no avail.  The fish was just too big, and the bird could never figure out how to get it in its hungry bill.  When a fisherman approached, he grabbed his catch, flew back out over the lake, and accidentally dropped the fish!!<br/> <br/>O well, win some-lose some.<br/> <br/>Thanks again :)</td>', 'Thanks for all the positive comments! This one was great fun, and at 5.9+ I believe I''ve made it to one of the infamous groups here on DPC! This juvenile yellow crowned night heron(?) snagged this meal from a lake near my apartment, dropped it on the levee he''s standing on, and fought for 20 minutes to no avail.  The fish was just too big, and the bird could never figure out how to get it in its hungry bill.  When a fisherman approached, he grabbed his catch, flew back out over the lake, and accidentally dropped the fish!! O well, win some-lose some. Thanks again :)', '2010-08-04 01:10:11.000000', NULL, 0),
(6116502, 900055, 59029, '<td valign="top">Gorgeous shot, Timfy!  Huge congrats...now can I have the recipe please? :-)</td>', 'Gorgeous shot, Timfy!  Huge congrats...now can I have the recipe please? :-)', '2010-08-04 01:11:28.000000', NULL, 0),
(6116510, 900037, 59029, '<td valign="top">Congrats on the red and a lovely shot of that amazing cuisine.  Hope it was as good as it looks!</td>', 'Congrats on the red and a lovely shot of that amazing cuisine.  Hope it was as good as it looks!', '2010-08-04 01:13:04.000000', NULL, 0),
